@Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        int n = Integer.parseInt(getParameter("n"));
        int m = Integer.parseInt(getParameter("m"));
        List<V> leftPartition = new ArrayList<>();
        List<V> rightPartition = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            V vertex = createVertex("L" + i);
            leftPartition.add(vertex);
            target.addVertex(vertex);
            resultMap.put("L" + i, vertex);
        }
        for (int i = 0; i < m; i++) {
            V vertex = createVertex("R" + i);
            rightPartition.add(vertex);
            target.addVertex(vertex);
            resultMap.put("R" + i, vertex);
        }
        for (V leftVertex : leftPartition) {
            for (V rightVertex : rightPartition) {
                E edge = createEdge(leftVertex, rightVertex);
                target.addEdge(leftVertex, rightVertex, edge);
            }
        }
    }

