public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings diff = new Mappings();
    if (mappings == null) {
        return diff;
    }

    // Get the current mappings for the table
    Mappings currentMappings = getCurrentMappings(tableName);
    if (currentMappings == null) {
        return mappings;
    }

    // Compare fields and add those that exist in input but not in current
    if (mappings.getFields() != null) {
        for (String fieldName : mappings.getFields().keySet()) {
            if (!currentMappings.getFields().containsKey(fieldName)) {
                diff.addField(fieldName, mappings.getFields().get(fieldName));
            }
        }
    }

    // Do not include _source configuration to avoid conflicts
    return diff;
}

