static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    // Convert to a date-like structure to compute the day of the year
    // We need to find the start of the current "step" period
    // The step is based on days within the month, starting from day 1
    // For dayStep = 11:
    //   days 1-11 -> 1
    //   days 12-22 -> 12
    //   days 23-31 -> 23

    // Calculate the bucket start day
    long bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;

    // Ensure bucketStartDay does not exceed the number of days in the month
    // We need to know the number of days in the month
    int daysInMonth;
    switch ((int) month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31;
            break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30;
            break;
        case 2:
            // Check for leap year
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                daysInMonth = 29;
            } else {
                daysInMonth = 28;
            }
            break;
        default:
            daysInMonth = 30; // fallback
            break;
    }

    if (bucketStartDay > daysInMonth) {
        bucketStartDay = daysInMonth;
    }

    return year * 10000 + month * 100 + bucketStartDay;
}

