public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double midX = (box.getMinX() + box.getMaxX()) / 2.0;
    Box2D leftBox = new Box2D(box.getMinX(), midX, box.getMinY(), box.getMaxY());
    Box2D rightBox = new Box2D(midX, box.getMaxX(), box.getMinY(), box.getMaxY());
    return new Pair<>(leftBox, rightBox);
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int newSize = Math.max(this.size + size, this.size * 2);
    byte[] newBuffer = new byte[newSize];
    System.arraycopy(this.buffer, 0, newBuffer, 0, this.size);
    this.buffer = newBuffer;
}

