private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; ++i) {
        int type = currentFrame[i];
        if (type == Opcodes.TOP) {
            stackMapTableEntries.putShort((short) 0);
        } else if (type == Opcodes.INTEGER) {
            stackMapTableEntries.putShort((short) 1);
        } else if (type == Opcodes.FLOAT) {
            stackMapTableEntries.putShort((short) 2);
        } else if (type == Opcodes.LONG) {
            stackMapTableEntries.putShort((short) 4);
        } else if (type == Opcodes.DOUBLE) {
            stackMapTableEntries.putShort((short) 3);
        } else if (type == Opcodes.NULL) {
            stackMapTableEntries.putShort((short) 5);
        } else if (type == Opcodes.UNINITIALIZED_THIS) {
            stackMapTableEntries.putShort((short) 6);
        } else {
            int index = type & 0xFFFF;
            if (index >= 64000) {
                stackMapTableEntries.putShort((short) 8);
                stackMapTableEntries.putShort((short) (index - 64000));
            } else {
                stackMapTableEntries.putShort((short) (7 + index));
            }
        }
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream must not be null");
    }
    // Clear the buffer
    buffer = new byte[0];
    // Read all bytes from the input stream
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] buffer = new byte[4096];
    int bytesRead;
    while ((bytesRead = in.read(buffer)) != -1) {
        baos.write(buffer, 0, bytesRead);
    }
    // Store the bytes in the buffer
    this.buffer = baos.toByteArray();
    // Reset the read pointer to the start
    readPointer = 0;
}

