protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0, new ArrayList<>());
    }

    // Find a starting vertex
    V start = null;
    for (E edge : tour) {
        start = graph.getEdgeSource(edge);
        break;
    }

    // Build the path by traversing edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>(tour);

    V current = start;
    vertices.add(current);

    while (!usedEdges.isEmpty()) {
        E nextEdge = null;
        for (E edge : usedEdges) {
            if (graph.getEdgeSource(edge).equals(current) || graph.getEdgeTarget(edge).equals(current)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            break; // No more edges to traverse
        }

        edges.add(nextEdge);
        usedEdges.remove(nextEdge);

        V nextVertex;
        if (graph.getEdgeSource(nextEdge).equals(current)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            nextVertex = graph.getEdgeSource(nextEdge);
        }

        vertices.add(nextVertex);
        current = nextVertex;
    }

    // Calculate the total weight
    double weight = 0;
    for (E edge : edges) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, start, current, weight, edges);
}

