    if (arr == null || from < 0 || to >= arr.length || from > to) {
        return;
    }
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this) {
        return;
    }
    ListNode<E> first = list.first;
    if (first == null) {
        return;
    }
    ListNode<E> last = list.last;
    list.first = null;
    list.last = null;
    list.size = 0;
    if (this.first == null) {
        this.first = first;
        this.last = last;
    } else {
        this.last.next = first;
        first.prev = this.last;
        this.last = last;
    }
    this.size += list.size;
}

