    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    int i = nameStart;
    // Skip leading whitespace
    while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
        i++;
    }
    if (i >= name.length()) {
        return;
    }
    // Append first character
    buf.append(name.charAt(i));
    i++;
    // Skip whitespace
    while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
        i++;
    }
    // Append subsequent initials
    while (i < name.length()) {
        // Skip non-alphabetic characters
        while (i < name.length() && !Character.isLetter(name.charAt(i))) {
            i++;
        }
        if (i >= name.length()) {
            break;
        }
        // Append the letter
        buf.append(Character.toUpperCase(name.charAt(i)));
        i++;
        // Skip the rest of the word
        while (i < name.length() && Character.isLetter(name.charAt(i))) {
            i++;
        }
        // Skip whitespace
        while (i < name.length() && Character.isWhitespace(name.charAt(i))) {
            i++;
        }
    }
}

