public static String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

