public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Normalize the path by removing trailing slash if present
    String normalizedPath = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;

    // If relative path starts with "/", it's an absolute path, return it as is
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Combine the path and relative path
    String combinedPath = normalizedPath + "/" + relativePath;

    // Normalize the combined path by resolving "." and ".." segments
    String[] parts = combinedPath.split("/");
    List<String> result = new ArrayList<>();

    for (String part : parts) {
        if (part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!result.isEmpty()) {
                result.remove(result.size() - 1);
            }
        } else if (!part.isEmpty()) {
            result.add(part);
        }
    }

    // Reconstruct the path
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < result.size(); i++) {
        if (i > 0) {
            sb.append("/");
        }
        sb.append(result.get(i));
    }

    // If the original path started with "/", ensure the result does too
    if (path.startsWith("/") && sb.length() > 0) {
        sb.insert(0, "/");
    }

    return sb.toString();
}

